const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laPalma = ee.Geometry.Point(-17.86, 28.66); // Approximate centroid of La Palma
  const analysisGeometry = laPalma.buffer(25000); // 25 km buffer around La Palma

  const date1_start = '2023-07-15';
  const date1_end = '2023-07-16';
  const date2_start = '2023-07-17';
  const date2_end = '2023-07-18';

  // 2. Data Acquisition & Check
  const fireCollection = ee.ImageCollection('FIRMS/VIIRS/NRT_FIRMS_VIIRS');

  // Filter for Period 1
  const firesP1 = fireCollection
    .filterDate(date1_start, date1_end)
    .filterBounds(analysisGeometry);

  const firesP1_size = await firesP1.size().getInfo();
  if (firesP1_size === 0) {
    console.log(`No VIIRS fire detections for Period 1 (${date1_start} to ${date1_end}).`);
    // This is a valid scenario, meaning no fires were detected.
  }

  // Filter for Period 2
  const firesP2 = fireCollection
    .filterDate(date2_start, date2_end)
    .filterBounds(analysisGeometry);

  const firesP2_size = await firesP2.size().getInfo();
  if (firesP2_size === 0) {
    console.log(`No VIIRS fire detections for Period 2 (${date2_start} to ${date2_end}).`);
    // This is a valid scenario.
  }

  // Check if both collections are empty - if no fire data *at all* for the periods
  if (firesP1_size === 0 && firesP2_size === 0) {
      console.log("No VIIRS fire detections for either period in La Palma.");
      console.log("C1"); // No relevant data found, but due to no detections, not missing collection
      return;
  }

  // 3. Processing & 4. Calculation
  // Calculate total Fire Radiative Power (FRP) for each period
  // FRP is a measure of fire intensity. Summing it gives an aggregate measure of fire presence.
  const calculateTotalFRP = async (collection, periodName) => {
    if (await collection.size().getInfo() === 0) {
      return 0; // No fires, so total FRP is 0
    }

    // Convert to feature collection to sum 'frp' from all points
    const fireFeatures = ee.FeatureCollection(collection.map(image => {
      // Get all features (fire points) in the image
      return image.select(['frp']).reduceToPoints({
        reducer: ee.Reducer.mean().setOutputs(['frp']), // Get frp value at each point
        scale: 375, // VIIRS pixel scale
        crs: image.projection(),
        tileScale: 16 // Increase tileScale to avoid memory errors for large areas
      });
    })).flatten();

    // Sum the 'frp' band for all fire features within the geometry
    const totalFRP = await fireFeatures.reduceColumns({
      reducer: ee.Reducer.sum(),
      selectors: ['frp']
    }).get('sum').getInfo();

    // Ensure totalFRP is a number, default to 0 if null/undefined (e.g., no points after reduction)
    return totalFRP === null ? 0 : totalFRP;
  };

  const totalFRP_P1 = await calculateTotalFRP(firesP1, 'Period 1');
  const totalFRP_P2 = await calculateTotalFRP(firesP2, 'Period 2');

  // 5. Validation & Final Answer
  console.log(`Period 1 (${date1_start} to ${date1_end}) Images: ${firesP1_size}, Total FRP: ${totalFRP_P1.toFixed(2)}`);
  console.log(`Period 2 (${date2_start} to ${date2_end}) Images: ${firesP2_size}, Total FRP: ${totalFRP_P2.toFixed(2)}`);

  if (totalFRP_P1 === null || totalFRP_P2 === null) {
    console.log("C3"); // Calculation failure if FRP is null
    return;
  }

  // Check if totalFRP_P1 is 0 and totalFRP_P2 is also 0, or if totalFRP_P1 < totalFRP_P2.
  // The question asks if fire presence *decreased*.
  if (totalFRP_P2 < totalFRP_P1) {
    console.log("A"); // Yes, active fire presence decreased.
  } else {
    console.log("B"); // No, active fire presence did not decrease (it stayed the same or increased).
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
